export type Appearance = "purple" | "vercel";

export function isWorkspacePath(pathname: string): boolean {
  if (pathname === "/usage/return" || pathname === "/usage/return/")
    return false;
  return /^\/(compose|templates|contacts|history|usage|settings|billing)(\/|$)/.test(
    pathname,
  );
}

export function parseAppearance(value: string | null): Appearance {
  return value === "vercel" ? "vercel" : "purple";
}
